WFJ.Data.add("gossip", {
  ["de0116d951a77c09"] = { "Meraviglioso! Ti ringraziamo per la tua generosa donazione, {name}!", "." },
  ["de01371c2cf0849b"] = { "La mia furia è scatenata!", "." },
  ["de027b039a1ff333"] = { "Il mio forziere è di ingegnosa fattura e per aprirlo servono due chiavi, una d'oro e una d'argento. La prima chiave, quella d'argento, l'ho data al mio primo ufficiale, e io ho tenuto quella d'oro.\n\nMa eravamo destinati a perderle. La mia chiave è andata perduta durante l'attacco successivo dei naga, e quella del mio primo ufficiale un giorno dopo, quando i drysnap makrura ci hanno assaliti e lo hanno trascinato negli abissi.\n\nDi certo i naga e i makrura hanno le chiavi. Per fortuna sono nemici e non se le divideranno.", "." },
  ["de042fc3773d35c8"] = { "%s torna da {name}.", "." },
  ["de0ed23fa5c69377"] = { "Sai perché gli occhi degli orchi brillano di rosso? Perché bevono sangue!", "." },
  ["de1ca14b0e9f89ae"] = { "Troverai Carolai Anise all'estremità nord-ovest del paese, intenta a far saltare in aria casa sua. Perché non vai a vedere se puoi aiutarla?", "." },
  ["de1d11697b8554a6"] = { "Nessuno può distruggermi! Per volere di Ragnaros, rinascerò!", "." },
  ["de2cc32b43f79db9"] = { "Banca di ⟦Stormwind=Roccavento⟧", "." },
  ["de2ccab9315dd6df"] = { "<Benvenuto/Benvenuta> al Castello di Roccavento, <cittadino/cittadina>.", "." },
  ["de2d95ecb4059e36"] = { "Mi aggrapperò all'amore di mia figlia e spererò di trovare il perdono della Luce per i miei peccati.", "." },
  ["de3b61fcc07388b0"] = { "Il Fortilizio di Brinarossa è sotto attacco! Se nessuno interviene, l'⟦Horde=Orda⟧ lo distruggerà!", "." },
  ["de3cabf614dd1571"] = { "Il tempo della conquista si avvicina rapidamente.", "." },
  ["de444ee643bc8b69"] = { "Omarion, l'artigianato non fa per me. Puoi aiutarmi lo stesso?", "." },
  ["de44a003d8d4ec36"] = { "<⟦Lord Arkkoroc=Sire Arkkoroc⟧ si china per esaminarti.>\n\nDove sono?", "." },
  ["de49331c3c73987f"] = { "Nel villaggio non abbiamo un posto del genere. Ma le vette altissime del ⟦Thunder Bluff=Picco del Tuono⟧ sì. Va' a nord lungo la strada che esce dal ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧ finché arrivi ai piedi delle alture. Lì prendi l'ascensore fino in cima e parla con un ⟦Bluffwatcher=Guardiano del Picco⟧. Che i tuoi antenati veglino su di te.", "." },
  ["de4a7fcd78d35c62"] = { "Brindo a qualsiasi cosa!", "." },
  ["de4e06caff8add05"] = { "Mi interessa l'addestramento da mago.", "." },
  ["de50a21650707a04"] = { "Mi sembri un po' <sperduto/sperduta>. Posso aiutarti a trovare qualcosa?", "." },
  ["de5376d33a777558"] = { "Il mio potere è sconquassantemente devastante! È ridicolo che questi mortali tentino anche solo di entrare nel mio regno!", "." },
  ["de54029735395e67"] = { "Le ⟦The Barrens=Savane⟧ racchiudono una ricchezza di sostanze a cui noi, gli speziali di Lordaeron, potremmo trovare un uso.", "." },
  ["de57a48ef32e7e71"] = { "Perché hai fatto cose tanto orribili?", "." },
  ["de5a3b799ab2988b"] = { "Se invertiamo i flussi dell'Essenza, forse possiamo alterare la polarità.", "." },
  ["de5f3f6f229b9472"] = { "Fammi vedere cosa sai fare!", "." },
  ["de64be9357099a14"] = { "Devi aprire il ⟦Felhound Tracker Kit=Corredo per Vilsegugio Braccatore⟧ e leggere il manuale d'istruzioni. Evoca la bestia quando ti trovi nei pressi della penisola dei giganti delle scogliere, a sud di qui.", "." },
  ["de6671353c36b022"] = { "Vedo che quegli idioti dell'Abbazia ci hanno mandato carne fresca.", "." },
  ["de6f8e407eb79759"] = { "I Paragons of Power sono mojo potente. Sono mojo dell'Impero Gurubashi. Noi Zandalari dobbiamo prendere il mojo. La tribù prenderà il mojo per sé. Il Dio del Sangue non ci distruggerà.\n\nCi sono tre tipi di Paragons a ⟦Zul'Gurub=Zul'gurub⟧. Cerca monete. Cerca bijou. Cerca oggetti primordiali. Questi sono i Paragons.\n\nVa' a ⟦Zul'Gurub=Zul'gurub⟧ ora. Uccidi. Prendi i Paragons of Power. Portali alla tribù. Guadagna il nostro rispetto. Guadagna il nostro equipaggiamento da battaglia. Guadagna il vero potere.", "." },
  ["de7fbb35a73e36bf"] = { "Impugni la lama di mio padre, {name}. I miei soldati sono ai tuoi ordini, <mio/mia> <signore/signora>. Prendili... Guidali... Gli impuri devono essere epurati. Devono essere mondati dalla loro corruzione.", "." },
  ["de80a0711d0627a9"] = { "Cos'è questo potere che scorre in me? È questo il potere dello sciamanesimo di cui parlava Tor'gan...?", "." },
  ["de84a394dcb8e632"] = { "Questa terra ora appartiene alla ⟦Defias Brotherhood=Fratellanza dei Defias⟧!", "." },
  ["de8eb1323c02c6ff"] = { "HO DETTO BUONA GIORNATA!", "." },
  ["de9204b3a84e23f9"] = { "I miei poteri sono tornati e voi avete sprecato la vostra occasione, sciocchi mortali. Alla prossima.", "." },
  ["de951e6f8c2b7e71"] = { "Non dare retta a quel vecchio pazzo, <ragazzo/ragazza>. Fa così con tutti. Però ti ho tenuto d'occhio: hai vero talento. Vieni a fare due chiacchiere con me.", "." },
  ["de95298ca26ecb97"] = { "Non basta! Difensori, radunatevi al centro del paese. Insieme resisteremo al mostro non morto!", "." },
  ["de9d6806cf9d1d20"] = { "Prima Kormok spezza tue ossa! Poi Kormok brucia tua anima!", "." },
  ["de9f262bad39a0bd"] = { "Squadra blu, vincitrice!", "." },
  ["dea9b05def876c2d"] = { "Parlami del ⟦Portals Deck=Mazzo dei Portali⟧.", "." },
  ["deaf55ca4f7f1f5f"] = { "comincia a creparsi!", "." },
  ["deb10d2e1603c5ec"] = { "Anch'io sono felice di vederti, Grim! A quanto pare non tutti gli stranieri sono da temere, eh, Grim? Terenthis saprà ricompensare a dovere chi ci ha aiutati.", "." },
  ["deb475c1fd9f8097"] = { "Hai imparato tutto ciò che posso insegnarti, {name}. Permettimi di darti un ultimo consiglio: scegli con giudizio il tuo primo famiglio. Sceglierai una creatura della terra, dell'acqua o del cielo? Qualunque sia, senza dubbio il tuo famiglio starà con te per molto tempo.\n\nEcco a te, {name}. Ora ti darò il potere di addomesticare una bestia, e di richiamarla e congedarla come meglio credi. Usa le tue nuove abilità con orgoglio: te le sei guadagnate.", "." },
  ["deb73f3d66079a83"] = { "Ora, dov'era quel libro sulle usanze degli elfi della notte che stavo cercando...", "." },
  ["deb805650f20433a"] = { "Non divorate subito tutto il cadavere, figlioli! Lasciate spazio per il dessert!", "." },
  ["deb81371181fe4bf"] = { "Tutto fatto!", "." },
  ["deb98a8b22c1a5b3"] = { "%s ringhia nella tua direzione prima di prendersi il tempo di annusarti.", "." },
  ["debcc7bd3ee55d80"] = { "%s scintilla, lampeggia... e svanisce!", "." },
  ["debf5af8ce033fbb"] = { "Addio, ⟦Goldshire=Borgodoro⟧. Tornerò abbastanza presto... forse tra una settimana.", "." },
  ["dec6051dc96179c8"] = { "%s salta nel pozzo lunare e si immerge...", "." },
  ["decdafc30bcf841d"] = { "È tutto compiuto, giovane {class}. Proprio mentre parliamo, sia l'⟦Horde=Orda⟧ sia l'⟦Alliance=Alleanza⟧ stanno trasportando le ultime merci per la guerra a ⟦Silithus=Silitus⟧, vicino alla ⟦Cenarion Hold=Fortezza Cenariana⟧, e l'operazione dovrebbe concludersi in meno di $2113w giorni. Dopodiché si potrà suonare il gong vicino ai cancelli di ⟦Ahn'Qiraj=Ahn'qiraj⟧, e la guerra avrà inizio.", "." },
  ["deceb6c7d5b22947"] = { "Grazie mille!", "." },
  ["ded71d76db93a67a"] = { "Costruita dodicimila anni fa da una setta segreta di stregoni elfi della notte, l'antica città di Eldre'Thalas serviva a proteggere i più preziosi segreti arcani della regina Azshara. Benché devastata dalla Grande Separazione del mondo, gran parte della meravigliosa città è ancora in piedi: è l'imponente ⟦Dire Maul=Maglio Infausto⟧. I tre distinti quartieri delle rovine sono stati invasi da ogni genere di creatura, soprattutto spettrali Alti Nobili, immondi satiri e ogre brutali.", "." },
  ["ded8fb8fe3504cd2"] = { "Non tutti gli ordini vanno secondo i piani. Per quanto ci impegniamo perché ogni consegna arrivi integra e in tempo, il recente aumento di bestie, banditi e perfino attacchi dell'⟦Horde=Orda⟧ causa purtroppo alcune inevitabili perdite di merci.\r\n\nSe trovi una spedizione smarrita e ti senti particolarmente disponibile, puoi dare un'occhiata all'etichetta e identificarne il contenuto previsto. Non è certo compito tuo rimediare alle nostre mancanze, ma se completi la spedizione riceverai una ricompensa adeguata.\r\n\nLa signora Baker, vicino alle casse, si occuperà del tuo compenso, e da lì penseremo noi alla logistica.", "." },
  ["dee17d119d76c776"] = { "Montate la guardia: gli intrusi sono vicini.", "." },
  ["dee608aeffc23eaa"] = { "Finalmente l'agonia finisce. Ho deluso voi, mia regina. Ho deluso tutti noi...", "." },
  ["dee69935bb10aa61"] = { "Ehi, che succede laggiù? Signore, tutto bene? Signore??", "." },
  ["dee946a6b1441ea2"] = { "Ah, eccoti, {name}. Ora vediamo che storia raccontano queste teste...", "." },
  ["deee628923a821ee"] = { "PER FORGIARDENTE!", "." },
  ["def01a7f2330aa34"] = { "La ⟦Emerald Circle=Fede di Smeraldo⟧ si impegna a guarire la terra ferita di ⟦Felwood=Vilbosco⟧. Anche se questa terra prende il nome proprio da ciò che l'ha corrotta, speriamo di riuscire un giorno a estirparne la corruzione.", "." },
  ["defa10bc7a2de8b4"] = { "Ti prendi gioco di me ora che non posso difendermi, con questa palla di ferro al piede?", "." },
  ["defc7ee27a6bddb4"] = { "Posso insegnarti l'arte della pesca.", "." },
})
